            sosa:resultTime ?t ;
            sosa:hasResult ?res .

        ?res qudt:numericValue ?val .

        BIND(YEAR(?t) AS ?year)
        FILTER(?year = 2002)

        BIND(MONTH(?t) AS ?month)
      }
      GROUP BY ?month
      ORDER BY DESC(?meanMonthlyFlow)
      LIMIT 1
    }
  }
}

